export const dict = LANGS.reduce((acc, lang, idx) => {
  acc[lang] = {};
  ROWS.forEach((row) => { acc[lang][row[0]] = row[idx + 1]; });
  return acc;
}, {});

export function t(lang, key) {
  return (dict[lang] && dict[lang][key]) || dict.en[key] || key;
}
